122		private static PKCS8EncodedKeySpec createKeySpecForSec1Ec(byte[] bytes, @Nullable String password) {
123			DerElement ecPrivateKey = DerElement.of(bytes);
124			Assert.state(ecPrivateKey != null, "Unable to find private key");
125			Assert.state(ecPrivateKey.isType(ValueType.ENCODED, TagType.SEQUENCE),
126					"Key spec should be an ASN.1 encoded sequence");
127			DerElement version = DerElement.of(ecPrivateKey.getContents());
128			Assert.state(version != null && version.isType(ValueType.PRIMITIVE, TagType.INTEGER),
129					"Key spec should start with version");
130			Assert.state(version.getContents().remaining() == 1 && version.getContents().get() == 1,
131					"Key spec version must be 1");
132			DerElement privateKey = DerElement.of(ecPrivateKey.getContents());
133			Assert.state(privateKey != null && privateKey.isType(ValueType.PRIMITIVE, TagType.OCTET_STRING),
134					"Key spec should contain private key");
135			DerElement parameters = DerElement.of(ecPrivateKey.getContents());
136			return createKeySpecForAlgorithm(bytes, ELLIPTIC_CURVE_ALGORITHM, getEcParameters(parameters));
137		}
138	
139		private static EncodedOid getEcParameters(@Nullable DerElement parameters) {
140			if (parameters == null) {
141				return ELLIPTIC_CURVE_384_BIT;
142			}
143			Assert.state(parameters.isType(ValueType.ENCODED), "Key spec should contain encoded parameters");
144			DerElement contents = DerElement.of(parameters.getContents());
145			Assert.state(contents != null && contents.isType(ValueType.PRIMITIVE, TagType.OBJECT_IDENTIFIER),
146					"Key spec parameters should contain object identifier");
147			return EncodedOid.of(contents);
148		}
149	
150		private static PKCS8EncodedKeySpec createKeySpecForAlgorithm(byte[] bytes, EncodedOid algorithm,
151				@Nullable EncodedOid parameters) {
152			try {
153				DerEncoder encoder = new DerEncoder();
154				encoder.integer(0x00); // Version 0
155				DerEncoder algorithmIdentifier = new DerEncoder();
156				algorithmIdentifier.objectIdentifier(algorithm);
157				algorithmIdentifier.objectIdentifier(parameters);
158				encoder.sequence(algorithmIdentifier.toByteArray());
159				encoder.octetString(bytes);
160				return new PKCS8EncodedKeySpec(encoder.toSequence());
161			}
162			catch (IOException ex) {
163				throw new IllegalStateException(ex);
164			}
165		}
