167		private static PKCS8EncodedKeySpec createKeySpecForPkcs8(byte[] bytes, @Nullable String password) {
168			DerElement ecPrivateKey = DerElement.of(bytes);
169			Assert.state(ecPrivateKey != null, "Unable to find private key");
170			Assert.state(ecPrivateKey.isType(ValueType.ENCODED, TagType.SEQUENCE),
171					"Key spec should be an ASN.1 encoded sequence");
172			DerElement version = DerElement.of(ecPrivateKey.getContents());
173			Assert.state(version != null && version.isType(ValueType.PRIMITIVE, TagType.INTEGER),
174					"Key spec should start with version");
175			DerElement sequence = DerElement.of(ecPrivateKey.getContents());
176			Assert.state(sequence != null && sequence.isType(ValueType.ENCODED, TagType.SEQUENCE),
177					"Key spec should contain private key");
178			DerElement algorithmId = DerElement.of(sequence.getContents());
179			Assert.state(algorithmId != null && algorithmId.isType(ValueType.PRIMITIVE, TagType.OBJECT_IDENTIFIER),
180					"Key spec container object identifier");
181			String algorithmName = ALGORITHMS.get(EncodedOid.of(algorithmId));
182			return (algorithmName != null) ? new PKCS8EncodedKeySpec(bytes, algorithmName) : new PKCS8EncodedKeySpec(bytes);
183		}
