198		/**
199		 * Parse a private key from the specified string, using the provided password for
200		 * decryption if necessary.
201		 * @param text the text to parse
202		 * @param password the password used to decrypt an encrypted private key
203		 * @return the parsed private key
204		 */
205		static @Nullable PrivateKey parse(@Nullable String text, @Nullable String password) {
206			if (text == null) {
207				return null;
208			}
209			try {
210				for (PemParser pemParser : PEM_PARSERS) {
211					PrivateKey privateKey = pemParser.parse(text, password);
212					if (privateKey != null) {
213						return privateKey;
214					}
215				}
216			}
217			catch (Exception ex) {
218				throw new IllegalStateException("Error loading private key file: " + ex.getMessage(), ex);
219			}
220			throw new IllegalStateException("Missing private key or unrecognized format");
221		}
