223		/**
224		 * Parser for a specific PEM format.
225		 */
226		private static class PemParser {
227	
228			private final Pattern pattern;
229	
230			private final BiFunction<byte[], @Nullable String, PKCS8EncodedKeySpec> keySpecFactory;
231	
232			private final String[] algorithms;
233	
234			PemParser(String header, String footer,
235					BiFunction<byte[], @Nullable String, PKCS8EncodedKeySpec> keySpecFactory, String... algorithms) {
236				this.pattern = Pattern.compile(header + BASE64_TEXT + footer, Pattern.CASE_INSENSITIVE);
237				this.keySpecFactory = keySpecFactory;
238				this.algorithms = algorithms;
239			}
240	
241			@Nullable PrivateKey parse(String text, @Nullable String password) {
242				Matcher matcher = this.pattern.matcher(text);
243				return (!matcher.find()) ? null : parse(decodeBase64(matcher.group(BASE64_TEXT_GROUP)), password);
244			}
245	
246			private static byte[] decodeBase64(String content) {
247				byte[] contentBytes = content.replace("\r", "").replace("\n", "").getBytes();
248				return Base64.getDecoder().decode(contentBytes);
249			}
250	
251			private @Nullable PrivateKey parse(byte[] bytes, @Nullable String password) {
252				PKCS8EncodedKeySpec keySpec = this.keySpecFactory.apply(bytes, password);
253				if (keySpec.getAlgorithm() != null) {
254					try {
255						KeyFactory keyFactory = KeyFactory.getInstance(keySpec.getAlgorithm());
256						return keyFactory.generatePrivate(keySpec);
257					}
258					catch (InvalidKeySpecException | NoSuchAlgorithmException ex) {
259						// Ignore
260					}
261				}
262				for (String algorithm : this.algorithms) {
263					try {
264						KeyFactory keyFactory = KeyFactory.getInstance(algorithm);
265						return keyFactory.generatePrivate(keySpec);
266					}
267					catch (InvalidKeySpecException | NoSuchAlgorithmException ex) {
268						// Ignore
269					}
270				}
271				return null;
272			}
273	
274		}
