276		/**
277		 * Simple ASN.1 DER encoder.
278		 */
279		static class DerEncoder {
280	
281			private final ByteArrayOutputStream stream = new ByteArrayOutputStream();
282	
283			void objectIdentifier(@Nullable EncodedOid encodedOid) throws IOException {
284				int code = (encodedOid != null) ? 0x06 : 0x05;
285				codeLengthBytes(code, (encodedOid != null) ? encodedOid.toByteArray() : null);
286			}
287	
288			void integer(int... encodedInteger) throws IOException {
289				codeLengthBytes(0x02, bytes(encodedInteger));
290			}
291	
292			void octetString(byte[] bytes) throws IOException {
293				codeLengthBytes(0x04, bytes);
294			}
295	
296			void sequence(byte[] bytes) throws IOException {
297				codeLengthBytes(0x30, bytes);
298			}
299	
300			void codeLengthBytes(int code, byte @Nullable [] bytes) throws IOException {
301				this.stream.write(code);
302				int length = (bytes != null) ? bytes.length : 0;
303				if (length <= 127) {
304					this.stream.write(length & 0xFF);
305				}
306				else {
307					ByteArrayOutputStream lengthStream = new ByteArrayOutputStream();
308					while (length != 0) {
309						lengthStream.write(length & 0xFF);
310						length = length >> 8;
311					}
312					byte[] lengthBytes = lengthStream.toByteArray();
313					this.stream.write(0x80 | lengthBytes.length);
314					for (int i = lengthBytes.length - 1; i >= 0; i--) {
315						this.stream.write(lengthBytes[i]);
316					}
317				}
318				if (bytes != null) {
319					this.stream.write(bytes);
320				}
321			}
322	
323			private static byte @Nullable [] bytes(int @Nullable ... elements) {
324				if (elements == null) {
325					return null;
326				}
327				byte[] result = new byte[elements.length];
328				for (int i = 0; i < elements.length; i++) {
329					result[i] = (byte) elements[i];
330				}
331				return result;
332			}
333	
334			byte[] toSequence() throws IOException {
335				DerEncoder sequenceEncoder = new DerEncoder();
336				sequenceEncoder.sequence(toByteArray());
337				return sequenceEncoder.toByteArray();
338			}
339	
340			byte[] toByteArray() {
341				return this.stream.toByteArray();
342			}
343	
344		}
