346		/**
347		 * An ASN.1 DER encoded element.
348		 */
349		static final class DerElement {
350	
351			private final ValueType valueType;
352	
353			private final long tagType;
354	
355			private final ByteBuffer contents;
356	
357			private DerElement(ByteBuffer bytes) {
358				byte b = bytes.get();
359				this.valueType = ((b & 0x20) == 0) ? ValueType.PRIMITIVE : ValueType.ENCODED;
360				this.tagType = decodeTagType(b, bytes);
361				int length = decodeLength(bytes);
362				bytes.limit(bytes.position() + length);
363				this.contents = bytes.slice();
364				bytes.limit(bytes.capacity());
365				bytes.position(bytes.position() + length);
366			}
367	
368			private long decodeTagType(byte b, ByteBuffer bytes) {
369				long tagType = (b & 0x1F);
370				if (tagType != 0x1F) {
371					return tagType;
372				}
373				tagType = 0;
374				b = bytes.get();
375				while ((b & 0x80) != 0) {
376					tagType <<= 7;
377					tagType = tagType | (b & 0x7F);
378					b = bytes.get();
379				}
380				return tagType;
381			}
382	
383			private int decodeLength(ByteBuffer bytes) {
384				byte b = bytes.get();
385				if ((b & 0x80) == 0) {
386					return b & 0x7F;
387				}
388				int numberOfLengthBytes = (b & 0x7F);
389				Assert.state(numberOfLengthBytes != 0, "Infinite length encoding is not supported");
390				Assert.state(numberOfLengthBytes != 0x7F, "Reserved length encoding is not supported");
391				Assert.state(numberOfLengthBytes <= 4, "Length overflow");
392				int length = 0;
393				for (int i = 0; i < numberOfLengthBytes; i++) {
394					length <<= 8;
395					length |= (bytes.get() & 0xFF);
396				}
397				return length;
398			}
399	
400			boolean isType(ValueType valueType) {
401				return this.valueType == valueType;
402			}
403	
404			boolean isType(ValueType valueType, TagType tagType) {
405				return this.valueType == valueType && this.tagType == tagType.getNumber();
406			}
407	
408			ByteBuffer getContents() {
409				return this.contents;
410			}
411	
412			static @Nullable DerElement of(byte[] bytes) {
413				return of(ByteBuffer.wrap(bytes));
414			}
415	
416			static @Nullable DerElement of(ByteBuffer bytes) {
417				return (bytes.remaining() > 0) ? new DerElement(bytes) : null;
418			}
419	
420			enum ValueType {
421	
422				PRIMITIVE, ENCODED
423	
424			}
425	
426			enum TagType {
427	
428				INTEGER(0x02), OCTET_STRING(0x04), OBJECT_IDENTIFIER(0x06), SEQUENCE(0x10);
429	
430				private final int number;
431	
432				TagType(int number) {
433					this.number = number;
434				}
435	
436				int getNumber() {
437					return this.number;
438				}
439	
440			}
441	
442		}
