444		/**
445		 * Decryptor for PKCS8 encoded private keys.
446		 */
447		static class Pkcs8PrivateKeyDecryptor {
448	
449			public static final String PBES2_ALGORITHM = "PBES2";
450	
451			static PKCS8EncodedKeySpec decrypt(byte[] bytes, @Nullable String password) {
452				Assert.state(password != null, "Password is required for an encrypted private key");
453				try {
454					EncryptedPrivateKeyInfo keyInfo = new EncryptedPrivateKeyInfo(bytes);
455					AlgorithmParameters algorithmParameters = keyInfo.getAlgParameters();
456					String encryptionAlgorithm = getEncryptionAlgorithm(algorithmParameters, keyInfo.getAlgName());
457					SecretKeyFactory keyFactory = SecretKeyFactory.getInstance(encryptionAlgorithm);
458					SecretKey key = keyFactory.generateSecret(new PBEKeySpec(password.toCharArray()));
459					Cipher cipher = Cipher.getInstance(encryptionAlgorithm);
460					cipher.init(Cipher.DECRYPT_MODE, key, algorithmParameters);
461					return keyInfo.getKeySpec(cipher);
462				}
463				catch (IOException | GeneralSecurityException ex) {
464					throw new IllegalArgumentException("Error decrypting private key", ex);
465				}
466			}
467	
468			private static String getEncryptionAlgorithm(@Nullable AlgorithmParameters algParameters, String algName) {
469				if (algParameters != null && PBES2_ALGORITHM.equals(algName)) {
470					return algParameters.toString();
471				}
472				return algName;
473			}
474	
475		}
