350		static void addBean(FormatterRegistry registry, Object bean, @Nullable ResolvableType beanType) {
351			if (bean instanceof GenericConverter converterBean) {
352				addBean(registry, converterBean, beanType, GenericConverter.class, registry::addConverter, (Runnable) null);
353			}
354			else if (bean instanceof Converter<?, ?> converterBean) {
355				Assert.state(beanType != null, "beanType is missing");
356				addBeanWithType(registry, converterBean, beanType, Converter.class, registry::addConverter,
357						ConverterBeanAdapter::new);
358			}
359			else if (bean instanceof ConverterFactory<?, ?> converterBean) {
360				Assert.state(beanType != null, "beanType is missing");
361				addBeanWithType(registry, converterBean, beanType, ConverterFactory.class, registry::addConverterFactory,
362						ConverterFactoryBeanAdapter::new);
363			}
364			else if (bean instanceof Formatter<?> formatterBean) {
365				addBean(registry, formatterBean, beanType, Formatter.class, registry::addFormatter, () -> {
366					Assert.state(beanType != null, "beanType is missing");
367					registry.addConverter(new PrinterBeanAdapter(formatterBean, beanType));
368					registry.addConverter(new ParserBeanAdapter(formatterBean, beanType));
369				});
370			}
371			else if (bean instanceof Printer<?> printerBean) {
372				Assert.state(beanType != null, "beanType is missing");
373				addBeanWithType(registry, printerBean, beanType, Printer.class, registry::addPrinter,
374						PrinterBeanAdapter::new);
375			}
376			else if (bean instanceof Parser<?> parserBean) {
377				Assert.state(beanType != null, "beanType is missing");
378				addBeanWithType(registry, parserBean, beanType, Parser.class, registry::addParser, ParserBeanAdapter::new);
