125		/**
126		 * Load the sources into the reader.
127		 */
128		void load() {
129			for (Object source : this.sources) {
130				load(source);
131			}
132		}
133	
134		private void load(Object source) {
135			Assert.notNull(source, "'source' must not be null");
136			if (source instanceof Class<?> type) {
137				load(type);
138				return;
139			}
140			if (source instanceof Resource resource) {
141				load(resource);
142				return;
143			}
144			if (source instanceof Package pack) {
145				load(pack);
146				return;
147			}
148			if (source instanceof CharSequence sequence) {
149				load(sequence);
150				return;
151			}
152			throw new IllegalArgumentException("Invalid source type " + source.getClass());
153		}
154	
155		private void load(Class<?> source) {
156			if (this.groovyReader != null && GroovyBeanDefinitionSource.class.isAssignableFrom(source)) {
157				// Any GroovyLoaders added in beans{} DSL can contribute beans here
158				GroovyBeanDefinitionSource loader = BeanUtils.instantiateClass(source, GroovyBeanDefinitionSource.class);
159				((GroovyBeanDefinitionReader) this.groovyReader).beans(loader.getBeans());
160			}
161			if (isEligible(source)) {
162				this.annotatedReader.register(source);
163			}
164		}
165	
166		private void load(Resource source) {
167			String filename = source.getFilename();
168			Assert.state(filename != null, "Source has no filename");
169			if (filename.endsWith(".groovy")) {
170				if (this.groovyReader == null) {
171					throw new BeanDefinitionStoreException("Cannot load Groovy beans without Groovy on classpath");
172				}
173				this.groovyReader.loadBeanDefinitions(source);
174			}
175			else {
176				this.xmlReader.loadBeanDefinitions(source);
177			}
178		}
179	
180		private void load(Package source) {
181			this.scanner.scan(source.getName());
182		}
183	
184		private void load(CharSequence source) {
185			String resolvedSource = this.scanner.getEnvironment().resolvePlaceholders(source.toString());
186			// Attempt as a Class
187			try {
188				load(ClassUtils.forName(resolvedSource, null));
189				return;
190			}
191			catch (IllegalArgumentException | ClassNotFoundException ex) {
192				// swallow exception and continue
193			}
194			// Attempt as Resources
195			if (loadAsResources(resolvedSource)) {
196				return;
197			}
198			// Attempt as package
199			Package packageResource = findPackage(resolvedSource);
200			if (packageResource != null) {
201				load(packageResource);
202				return;
203			}
204			throw new IllegalArgumentException("Invalid source '" + resolvedSource + "'");
205		}
206	
207		private boolean loadAsResources(String resolvedSource) {
208			boolean foundCandidate = false;
209			Resource[] resources = findResources(resolvedSource);
210			for (Resource resource : resources) {
211				if (isLoadCandidate(resource)) {
212					foundCandidate = true;
213					load(resource);
214				}
215			}
216			return foundCandidate;
217		}
218	
219		private boolean isGroovyPresent() {
220			return ClassUtils.isPresent("groovy.lang.MetaClass", null);
221		}
222	
223		private Resource[] findResources(String source) {
224			ResourceLoader loader = (this.resourceLoader != null) ? this.resourceLoader
225					: new PathMatchingResourcePatternResolver();
226			try {
227				if (loader instanceof ResourcePatternResolver resolver) {
228					return resolver.getResources(source);
229				}
230				return new Resource[] { loader.getResource(source) };
231			}
232			catch (IOException ex) {
233				throw new IllegalStateException("Error reading source '" + source + "'");
234			}
235		}
236	
237		private boolean isLoadCandidate(@Nullable Resource resource) {
238			if (resource == null || !resource.exists()) {
239				return false;
240			}
241			if (resource instanceof ClassPathResource classPathResource) {
242				// A simple package without a '.' may accidentally get loaded as an XML
243				// document if we're not careful. The result of getInputStream() will be
244				// a file list of the package content. We double-check here that it's not
245				// actually a package.
246				String path = classPathResource.getPath();
247				if (path.indexOf('.') == -1) {
248					try {
249						return getClass().getClassLoader().getDefinedPackage(path) == null;
250					}
251					catch (Exception ex) {
252						// Ignore
253					}
254				}
255			}
256			return true;
257		}
258	
259		private @Nullable Package findPackage(CharSequence source) {
260			Package pkg = getClass().getClassLoader().getDefinedPackage(source.toString());
261			if (pkg != null) {
262				return pkg;
263			}
264			try {
265				// Attempt to find a class in this package
266				ResourcePatternResolver resolver = new PathMatchingResourcePatternResolver(getClass().getClassLoader());
267				Resource[] resources = resolver
268					.getResources(ClassUtils.convertClassNameToResourcePath(source.toString()) + "/*.class");
269				for (Resource resource : resources) {
270					String filename = resource.getFilename();
271					Assert.state(filename != null, "No filename available");
272					String className = StringUtils.stripFilenameExtension(filename);
273					load(Class.forName(source + "." + className));
274					break;
275				}
276			}
277			catch (Exception ex) {
278				// swallow exception and continue
279			}
280			return getClass().getClassLoader().getDefinedPackage(source.toString());
281		}
