283		/**
284		 * Check whether the bean is eligible for registration.
285		 * @param type candidate bean type
286		 * @return true if the given bean type is eligible for registration, i.e. not a groovy
287		 * closure nor an anonymous class
288		 */
289		private boolean isEligible(Class<?> type) {
290			return !(type.isAnonymousClass() || isGroovyClosure(type) || hasNoConstructors(type));
291		}
292	
293		private boolean isGroovyClosure(Class<?> type) {
294			return GROOVY_CLOSURE_PATTERN.matcher(type.getName()).matches();
295		}
296	
297		private boolean hasNoConstructors(Class<?> type) {
298			Constructor<?>[] constructors = type.getDeclaredConstructors();
299			return ObjectUtils.isEmpty(constructors);
300		}
301	
302		/**
303		 * Simple {@link TypeFilter} used to ensure that specified {@link Class} sources are
304		 * not accidentally re-added during scanning.
305		 */
306		private static class ClassExcludeFilter extends AbstractTypeHierarchyTraversingFilter {
307	
308			private final Set<String> classNames = new HashSet<>();
