34	/**
35	 * Class used by {@link SpringApplication} to print the application banner.
36	 *
37	 * @author Phillip Webb
38	 */
39	class SpringApplicationBannerPrinter {
40	
41		static final String BANNER_LOCATION_PROPERTY = "spring.banner.location";
42	
43		static final String DEFAULT_BANNER_LOCATION = "banner.txt";
44	
45		private static final Banner DEFAULT_BANNER = new SpringBootBanner();
46	
47		private final ResourceLoader resourceLoader;
48	
49		private final @Nullable Banner fallbackBanner;
50	
51		SpringApplicationBannerPrinter(ResourceLoader resourceLoader, @Nullable Banner fallbackBanner) {
52			this.resourceLoader = resourceLoader;
53			this.fallbackBanner = fallbackBanner;
54		}
55	
56		Banner print(Environment environment, @Nullable Class<?> sourceClass, Log logger) {
57			Banner banner = getBanner(environment);
58			try {
59				logger.info(createStringFromBanner(banner, environment, sourceClass));
60			}
61			catch (UnsupportedEncodingException ex) {
62				logger.warn("Failed to create String for banner", ex);
63			}
64			return new PrintedBanner(banner, sourceClass);
65		}
66	
67		Banner print(Environment environment, @Nullable Class<?> sourceClass, PrintStream out) {
68			Banner banner = getBanner(environment);
69			banner.printBanner(environment, sourceClass, out);
70			return new PrintedBanner(banner, sourceClass);
71		}
72	
73		private Banner getBanner(Environment environment) {
74			Banner textBanner = getTextBanner(environment);
75			if (textBanner != null) {
76				return textBanner;
77			}
78			if (this.fallbackBanner != null) {
79				return this.fallbackBanner;
80			}
81			return DEFAULT_BANNER;
82		}
83	
84		private @Nullable Banner getTextBanner(Environment environment) {
85			String location = environment.getProperty(BANNER_LOCATION_PROPERTY, DEFAULT_BANNER_LOCATION);
86			Resource resource = this.resourceLoader.getResource(location);
87			try {
88				if (resource.exists() && !resource.getURL().toExternalForm().contains("liquibase-core")) {
89					return new ResourceBanner(resource);
90				}
91			}
92			catch (IOException ex) {
93				// Ignore
94			}
95			return null;
96		}
97	
98		private String createStringFromBanner(Banner banner, Environment environment,
99				@Nullable Class<?> mainApplicationClass) throws UnsupportedEncodingException {
100			String charset = environment.getProperty("spring.banner.charset", StandardCharsets.UTF_8.name());
101			ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
102			try (PrintStream out = new PrintStream(byteArrayOutputStream, false, charset)) {
103				banner.printBanner(environment, mainApplicationClass, out);
104			}
105			return byteArrayOutputStream.toString(charset);
106		}
107	
108		/**
109		 * Decorator that allows a {@link Banner} to be printed again without needing to
110		 * specify the source class.
111		 */
112		private static class PrintedBanner implements Banner {
113	
114			private final Banner banner;
115	
116			private final @Nullable Class<?> sourceClass;
117	
118			PrintedBanner(Banner banner, @Nullable Class<?> sourceClass) {
119				this.banner = banner;
120				this.sourceClass = sourceClass;
121			}
122	
123			@Override
124			public void printBanner(Environment environment, @Nullable Class<?> sourceClass, PrintStream out) {
125				sourceClass = (sourceClass != null) ? sourceClass : this.sourceClass;
126				this.banner.printBanner(environment, sourceClass, out);
127			}
128	
129		}
130	
131		static class SpringApplicationBannerPrinterRuntimeHints implements RuntimeHintsRegistrar {
132	
133			@Override
134			public void registerHints(RuntimeHints hints, @Nullable ClassLoader classLoader) {
135				hints.resources().registerPattern(DEFAULT_BANNER_LOCATION);
136			}
137	
138		}
139	
140	}
