41	/**
42	 * Interface that can be used to write JSON output. Typically used to generate JSON when a
43	 * dependency on a fully marshalling library (such as Jackson or Gson) cannot be assumed.
44	 * <p>
45	 * For standard Java types, the {@link #standard()} factory method may be used to obtain
46	 * an instance of this interface. It supports {@link String}, {@link Number} and
47	 * {@link Boolean} as well as {@link Collection}, {@code Array}, {@link Map} and
48	 * {@link WritableJson} types. Typical usage would be:
49	 *
50	 * <pre class="code">
51	 * JsonWriter&lt;Map&lt;String,Object&gt;&gt; writer = JsonWriter.standard();
52	 * writer.write(Map.of("Hello", "World!"), out);
53	 * </pre>
54	 * <p>
55	 * More complex mappings can be created using the {@link #of(Consumer)} method with a
56	 * callback to configure the {@link Members JSON members} that should be written. Typical
57	 * usage would be:
58	 *
59	 * <pre class="code">
60	 * JsonWriter&lt;Person&gt; writer = JsonWriter.of((members) -&gt; {
61	 *     members.add("first", Person::firstName);
62	 *     members.add("last", Person::lastName);
63	 *     members.add("dob", Person::dateOfBirth)
64	 *         .whenNotNull()
65	 *         .as(DateTimeFormatter.ISO_DATE::format);
66	 * });
67	 * writer.write(person, out);
68	 * </pre>
69	 * <p>
70	 * The {@link #writeToString(Object)} method can be used if you want to write the JSON
71	 * directly to a {@link String}. To write to other types of output, the
72	 * {@link #write(Object)} method may be used to obtain a {@link WritableJson} instance.
73	 *
74	 * @param <T> the type being written
75	 * @author Phillip Webb
76	 * @author Moritz Halbritter
77	 * @since 3.4.0
78	 */
79	@FunctionalInterface
80	public interface JsonWriter<T> {
81	
82		/**
83		 * Write the given instance to the provided {@link Appendable}.
84		 * @param instance the instance to write (may be {@code null}
85		 * @param out the output that should receive the JSON
86		 * @throws IOException on IO error
87		 */
88		void write(@Nullable T instance, Appendable out) throws IOException;
89	
90		/**
91		 * Write the given instance to a JSON string.
92		 * @param instance the instance to write (may be {@code null})
93		 * @return the JSON string
94		 */
95		default String writeToString(@Nullable T instance) {
96			return write(instance).toJsonString();
97		}
98	
99		/**
100		 * Provide a {@link WritableJson} implementation that may be used to write the given
101		 * instance to various outputs.
102		 * @param instance the instance to write (may be {@code null})
103		 * @return a {@link WritableJson} instance that may be used to write the JSON
104		 */
105		default WritableJson write(@Nullable T instance) {
106			return WritableJson.of((out) -> write(instance, out));
107		}
108	
109		/**
110		 * Return a new {@link JsonWriter} instance that appends a new line after the JSON has
111		 * been written.
112		 * @return a new {@link JsonWriter} instance that appends a new line after the JSON
113		 */
114		default JsonWriter<T> withNewLineAtEnd() {
115			return withSuffix("\n");
116		}
117	
118		/**
119		 * Return a new {@link JsonWriter} instance that appends the given suffix after the
120		 * JSON has been written.
121		 * @param suffix the suffix to write, if any
122		 * @return a new {@link JsonWriter} instance that appends a suffix after the JSON
123		 */
124		default JsonWriter<T> withSuffix(@Nullable String suffix) {
125			if (!StringUtils.hasLength(suffix)) {
126				return this;
127			}
128			return (instance, out) -> {
129				write(instance, out);
130				out.append(suffix);
131			};
132		}
133	
134		/**
135		 * Factory method to return a {@link JsonWriter} for standard Java types. See
136		 * {@link JsonValueWriter class-level javadoc} for details.
